// Preserves the original thrown value on cause while giving hooks a typed Error with a readable message.
function toHookError(error: unknown): Error {
  if (error instanceof Error) return error;
  const message = typeof error === 'string' ? error : inspect(error, {compact: true, breakLength: Infinity});
  return new Error(message, {cause: error});
}
